const PAdd = M.activate(fakeNode(ndAdd), ndAdd);
const longRow = rows(PAdd).find((r) => r.textContent.includes("Delete Geometry But Keep the Points"));
check("Add's long toggle label doesn't fit the value column -> whole row starts from the left (widechk), label doesn't wrap",
      longRow && longRow.classList.contains("widechk"));
const shortRow = rows(PS).find((r) => r.textContent.includes("Randomize Point Order"));
check("  short ones go in the value column as in Houdini", shortRow && !shortRow.classList.contains("widechk"));
check("  threshold: text + checkbox 18 > 186", M.wideCheck("x".repeat(24)) === false
      && M.wideCheck("Remove Degenerate Primitives") === true);

