W(nL, "color").value = "1"; PL.refresh();
lcf[2].value = "0.5"; fire(lcf[2], "change");
check("  original value has too few components ('1'): padded with 0 -> '1 0 0.5'", W(nL, "color").value === "1 0 0.5", W(nL, "color").value);
const ndT = F.nodes.PCG_Transform;
const nT = fakeNode(ndT);
