menus.length = 0;
rowBy(PT, "Group").querySelector("button").click();
check("group name ▾: upstream hasn't run -> a single hint in the menu", menus.length === 1
      && menus[0].items[0].content.includes("Upstream has not run yet"));
const PT2 = new M.Panel(nT, ndT, { names: () => [{ c: "prim", n: "top" }, { c: "point", n: "tip" }] });
menus.length = 0;
[...PT2.inner.querySelectorAll(".row")].find((r) => r.textContent.includes("Group"))
  .querySelector("button").click();
menus[0].items[0].callback();
check("  upstream has groups -> listed (with class), picking one writes group", J(menus[0].items.map((x) => x.content))
      === J(["prim: top", "point: tip"]) && W(nT, "group").value === "top");
const ndA = F.nodes.PCG_Add;
