sec("color picker / height measurement (pcg95, continued): tabs, sections, multiline text, the other two color pickers");
{
  const frame = () => new Promise((r) => requestAnimationFrame(() => r()));
  const spy = (P) => { const o = P.onResize; let n = 0; P.onResize = () => { n++; o?.(); };
                       return { get n() { return n; }, reset() { n = 0; }, undo() { P.onResize = o; } }; };
  await frame(); await frame();
  const sp = spy(PS);
  PS.inner.querySelectorAll(".tab")[2].click();
  check("switching tab: height measured on the spot", sp.n === 1, sp.n);
  PS.inner.querySelectorAll(".tab")[0].click();
  await frame(); await frame();
  sp.reset();
  const hd = PS.tabBtns[0].body.querySelector(".sechd") || PS.inner.querySelector(".sechd");
  hd.click();
  check("  collapsing a section: height measured on the spot", sp.n === 1, sp.n);
  hd.click();
  sp.undo();
  await frame(); await frame();
  const st = spy(PA);
  ta.value = Array.from({ length: 12 }, (_, i) => `${i} 0 0`).join("\n"); fire(ta, "input");
  check("  multiline text grows while typing: measured on the spot (counts even though only the value changed -- the caller said the height changed)", st.n === 1, st.n);
  st.undo();
  ta.value = W(nA, "points").value; fire(ta, "input");
  await frame(); await frame();
  // The other two color pickers (string color, ramp point) are also once per frame
  const lp = lc.querySelector("input[type=color]");
  for (const c of ["#ff0000", "#00ff00", "#0000ff"]) { lp.value = c; fire(lp, "input"); }
  const lv1 = W(nL, "color").value;
  await frame();
  check("Light Color's color picker: the first written immediately, later ones in the same frame write the latest on the next frame", lv1 === "1 0 0" && W(nL, "color").value === "0 0 1",
        J([lv1, W(nL, "color").value]));
  await frame(); await frame();
  selMode.value = "ramp_by_attribute"; fire(selMode, "change");
  W(nC, "ramp").value = "0:0,0,0  1:1,1,1"; PC.refresh();
  PC.ramps[0].state.sel = 1;
  const rp = rowBy(PC, "Attribute Ramp").querySelector("input[type=color]");
  for (const c of ["#ff0000", "#00ff00", "#0000ff"]) { rp.value = c; fire(rp, "input"); }
  const rv1 = W(nC, "ramp").value;
  await frame();
  check("  color picker of the selected ramp point: same", rv1 === "0:0,0,0  1:1,0,0" && W(nC, "ramp").value === "0:0,0,0  1:0,0,1",
        J([rv1, W(nC, "ramp").value]));
  selMode.value = "constant"; fire(selMode, "change");
  await frame(); await frame();
}

sec("takeover conditions, fallback to native");
check("nodes with a multiline code box are not taken over (Wrangle)", M.activate(fakeNode(F.nodes.PCG_Wrangle), F.nodes.PCG_Wrangle) === null
      && F.applies.PCG_Wrangle === false);
const nX = fakeNode(ndT);
nX.widgets.push({ name: "extra_js", type: "div", value: 1 });
check("nodes where another extension added custom widgets are not taken over", M.activate(nX, ndT) === null);
const nY = fakeNode(ndT);
nY.widgets.push({ name: "preview", type: "pcg_cop_preview", serialize: false });
const PY = M.activate(nY, ndT);
check("COP thumbnail can coexist: panel inserted before it (only moved within the non-serialized tail)",
      PY && nY.widgets[nY.widgets.length - 2].name === "pcg_panel"
      && nY.widgets[nY.widgets.length - 1].name === "preview");
const before = nC.widgets.slice(0, -1).map((w) => w.name);
M.deactivate(nC);
check("fallback to native: panel widget removed, native widgets shown again, order unchanged",
      !nC._pcgPanel && J(nC.widgets.map((w) => w.name)) === J(before)
      && nC.widgets.every((w) => w.hidden === false && w.type !== "pcg-collapsed"));
// ── wired parameters (pcg85: still shown on the panel, the slot dot aligned to that row)
const srcV = { id: 7, title: "Value (PCG)", type: "PCG_Value",
               outputs: [{ name: "float" }, { name: "int" }], widgets: [], inputs: [] };
const GZ = { _nodes: [srcV], links: { 5: { origin_id: 7, origin_slot: 0 } },
             getNodeById(id) { return this._nodes.find((n) => n.id === id) ?? null; } };
const nZ = fakeNode(ndT);
// In the real frontend these two are methods on the prototype (the panel wraps them on the instance)
Object.setPrototypeOf(nZ, { arrange() { this.arranged = (this.arranged || 0) + 1; },
                            getWidgetOnPos() { return this._pcgPanelWidget; } });
Object.assign(nZ, { id: 8, graph: GZ });
GZ._nodes.push(nZ);
nZ.inputs = [{ name: "geo" }, ...["tx", "ty", "tz", "rx"].map((n) => (
  { name: n, widget: { name: n }, link: n === "tx" ? 5 : null }))];
const PZ = M.activate(nZ, ndT);
const fld = (P, n) => P.inner.querySelector(`[data-w="${n}"]`);
check("wired parameters: native widget hidden too (no longer kept), the panel row still shown",
      W(nZ, "tx").hidden === true
      && !rows(PZ).find((r) => r.textContent.includes("Translate")).classList.contains("hidden"));
check("  the wired field shows '⇠ source node.output', marked lnk; other fields in the row as usual",
      fld(PZ, "tx").value === "⇠ Value (PCG).float" && fld(PZ, "tx").classList.contains("lnk")
      && !fld(PZ, "ty").classList.contains("lnk") && fld(PZ, "ty").value === "0",
      fld(PZ, "tx").value);
W(nZ, "tx").value = 3; PZ.sync(); PZ.refresh();
check("  sync doesn't write numbers back into a wired field", fld(PZ, "tx").value === "⇠ Value (PCG).float");
nZ.inputs[1].link = null; PZ.refresh();
check("  link removed: field goes back to the number", fld(PZ, "tx").value === "3" && !fld(PZ, "tx").classList.contains("lnk"),
      fld(PZ, "tx").value);
nZ.inputs[1].link = 5; PZ.refresh();
nZ.inputs[1].link = null; PZ.refresh();
check("  value never changed while wired, removing still writes back the number (no lingering '⇠ …')", fld(PZ, "tx").value === "3",
      fld(PZ, "tx").value);
nZ.inputs[1].link = 5; PZ.refresh();
nZ.inputs[2].link = 5; nZ.inputs[3].link = 5; PZ.refresh();
check("  all three components of a row wired: the row is still shown (before pcg85 it was hidden)",
      !rows(PZ).find((r) => r.textContent.includes("Translate")).classList.contains("hidden"));
nZ.inputs[2].link = null; nZ.inputs[3].link = null; PZ.refresh();

// Slot dots: jsdom can't measure layout, falls back to "top of the panel + 12"; the three components of a row are staggered by 5
nZ._pcgPanelWidget.y = 100;
nZ.arrange();
const py = (n) => nZ.inputs.find((i) => i.name === n).pos?.[1];
check("after arrange the slot dots move onto the panel (panel y + margin + row center), components of one row staggered",
      nZ.arranged === 1 && py("tx") === 100 + 4 + 12 - 5 && py("ty") === 116 && py("tz") === 121
      && nZ.inputs[1].pos[0] === 0
      && nZ.inputs[0].pos === undefined, J(nZ.inputs.map((i) => i.pos)));
// Link drop target: mouse over the ty field -> the widget the frontend asks for is the native ty (it uses it to find the slot)
const tyEl = fld(PZ, "ty");
tyEl.getBoundingClientRect = () => ({ left: 100, right: 150, top: 50, bottom: 70, width: 50, height: 20 });
